window.MishkatCats = [
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.",source:"صحيح البخاري (1)، وصحيح مسلم (1907) عن عمر. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"بُني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، والحج، وصوم رمضان.",source:"صحيح البخاري (8)، وصحيح مسلم (16) عن ابن عمر. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من أحدث في أمرنا هذا ما ليس منه فهو رد.",source:"صحيح البخاري (2697)، وصحيح مسلم (1718) عن عائشة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الدين النصيحة. قلنا: لمن؟ قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم.",source:"صحيح مسلم (55) عن تميم الداري."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"ما نهيتكم عنه فاجتنبوه، وما أمرتكم به فأتوا منه ما استطعتم.",source:"صحيح البخاري (7288)، وصحيح مسلم (1337) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إن الله طيب لا يقبل إلا طيبًا.",source:"صحيح مسلم (1015) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الحلال بيّن والحرام بيّن، وبينهما أمور مشتبهات، فمن اتقى الشبهات فقد استبرأ لدينه وعرضه.",source:"صحيح البخاري (52)، وصحيح مسلم (1599) عن النعمان بن بشير. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إن الله كتب الإحسان على كل شيء، فإذا قتلتم فأحسنوا القتلة، وإذا ذبحتم فأحسنوا الذبحة.",source:"صحيح مسلم (1955) عن شداد بن أوس."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه.",source:"صحيح البخاري (13)، وصحيح مسلم (45) عن أنس. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لا يحل دم امرئ مسلم إلا بإحدى ثلاث: الثيب الزاني، والنفس بالنفس، والتارك لدينه المفارق للجماعة.",source:"صحيح البخاري (6878)، وصحيح مسلم (1676) عن ابن مسعود. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لا تغضب.",source:"صحيح البخاري (6116) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"اتق الله حيثما كنت، وأتبع السيئة الحسنة تمحها، وخالق الناس بخلق حسن.",source:"سنن الترمذي (1987) عن أبي ذر وقال حسن صحيح."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"قل: آمنت بالله، ثم استقم.",source:"صحيح مسلم (38) عن سفيان بن عبد الله."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"المسلم من سلم المسلمون من لسانه ويده، والمهاجر من هجر ما نهى الله عنه.",source:"صحيح البخاري (10)، وصحيح مسلم (40) عن عبد الله بن عمرو. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لا يؤمن أحدكم حتى أكون أحب إليه من والده وولده والناس أجمعين.",source:"صحيح البخاري (15)، وصحيح مسلم (44) عن أنس. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"آية المنافق ثلاث: إذا حدّث كذب، وإذا وعد أخلف، وإذا اؤتمن خان.",source:"صحيح البخاري (33)، وصحيح مسلم (59) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من كان يؤمن بالله واليوم الآخر فليقل خيرًا أو ليصمت.",source:"صحيح البخاري (6018)، وصحيح مسلم (47) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"مثل المؤمنين في توادّهم وتراحمهم وتعاطفهم مثل الجسد إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى.",source:"صحيح البخاري (6011)، وصحيح مسلم (2586) عن النعمان بن بشير. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لا يدخل الجنة من كان في قلبه مثقال ذرة من كبر.",source:"صحيح مسلم (91) عن ابن مسعود."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الطهور شطر الإيمان.",source:"صحيح مسلم (223) عن أبي مالك الأشعري."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الإيمان بضع وسبعون شعبة، فأفضلها قول لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان.",source:"صحيح البخاري (9)، وصحيح مسلم (35) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من مات لا يشرك بالله شيئًا دخل الجنة.",source:"صحيح البخاري (1238)، وصحيح مسلم (93) عن أبي ذر. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"أُمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأن محمدًا رسول الله ويقيموا الصلاة ويؤتوا الزكاة.",source:"صحيح البخاري (25)، وصحيح مسلم (22) عن ابن عمر. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان مكفّرات لما بينهن إذا اجتُنبت الكبائر.",source:"صحيح مسلم (233) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"يسروا ولا تعسروا، وبشّروا ولا تنفّروا.",source:"صحيح البخاري (69)، وصحيح مسلم (1732) عن أنس. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من يرد الله به خيرًا يفقّهه في الدين.",source:"صحيح البخاري (71)، وصحيح مسلم (1037) عن معاوية. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"بلّغوا عني ولو آية.",source:"صحيح البخاري (3461) عن عبد الله بن عمرو."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من كذب عليّ متعمدًا فليتبوأ مقعده من النار.",source:"صحيح البخاري (110)، وصحيح مسلم (3). متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إن الله لا ينظر إلى صوركم وأموالكم، ولكن ينظر إلى قلوبكم وأعمالكم.",source:"صحيح مسلم (2564) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"اتقوا النار ولو بشق تمرة، فإن لم تجدوا فبكلمة طيبة.",source:"صحيح البخاري (1417)، وصحيح مسلم (1016) عن عدي بن حاتم. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"كل سُلامى من الناس عليه صدقة كل يوم تطلع فيه الشمس.",source:"صحيح البخاري (2989)، وصحيح مسلم (1009) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لا تحقرن من المعروف شيئًا ولو أن تلقى أخاك بوجه طلق.",source:"صحيح مسلم (2626) عن أبي ذر."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من لا يرحم لا يُرحم.",source:"صحيح البخاري (5997)، وصحيح مسلم (2319) عن جرير. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الراحمون يرحمهم الرحمن، ارحموا من في الأرض يرحمكم من في السماء.",source:"سنن الترمذي (1924) عن عبد الله بن عمرو وقال حسن صحيح."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"ليس الشديد بالصُّرَعة، إنما الشديد الذي يملك نفسه عند الغضب.",source:"صحيح البخاري (6114)، وصحيح مسلم (2609) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف، وفي كل خير. احرص على ما ينفعك واستعن بالله ولا تعجز.",source:"صحيح مسلم (2664) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"عجبًا لأمر المؤمن إن أمره كله خير: إن أصابته سراء شكر فكان خيرًا له، وإن أصابته ضراء صبر فكان خيرًا له.",source:"صحيح مسلم (2999) عن صهيب."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لا يُلدغ المؤمن من جحر واحد مرتين.",source:"صحيح البخاري (6133)، وصحيح مسلم (2998) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"المسلم أخو المسلم لا يظلمه ولا يسلمه، ومن كان في حاجة أخيه كان الله في حاجته.",source:"صحيح البخاري (2442)، وصحيح مسلم (2580) عن ابن عمر. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لا تباغضوا ولا تحاسدوا ولا تدابروا وكونوا عباد الله إخوانًا، ولا يحل لمسلم أن يهجر أخاه فوق ثلاث.",source:"صحيح البخاري (6065)، وصحيح مسلم (2559) عن أنس. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إياكم والظن فإن الظن أكذب الحديث، ولا تجسسوا ولا تحسسوا.",source:"صحيح البخاري (6066)، وصحيح مسلم (2563) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من غشّنا فليس منا.",source:"صحيح مسلم (101) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"سبعة يظلهم الله في ظله يوم لا ظل إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلّق بالمساجد، ورجلان تحابا في الله، ورجل دعته امرأة ذات منصب وجمال فقال إني أخاف الله، ورجل تصدّق فأخفاها، ورجل ذكر الله خاليًا ففاضت عيناه.",source:"صحيح البخاري (660)، وصحيح مسلم (1031) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الدنيا سجن المؤمن وجنة الكافر.",source:"صحيح مسلم (2956) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"كن في الدنيا كأنك غريب أو عابر سبيل.",source:"صحيح البخاري (6416) عن ابن عمر."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"نعمتان مغبون فيهما كثير من الناس: الصحة والفراغ.",source:"صحيح البخاري (6412) عن ابن عباس."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لو أنكم تتوكلون على الله حق توكله لرزقكم كما يرزق الطير تغدو خماصًا وتروح بطانًا.",source:"سنن الترمذي (2344) عن عمر وقال حسن صحيح."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"ليس الغنى عن كثرة العرض، ولكن الغنى غنى النفس.",source:"صحيح البخاري (6446)، وصحيح مسلم (1051) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"اتقوا الظلم فإن الظلم ظلمات يوم القيامة.",source:"صحيح مسلم (2578) عن جابر."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"سباب المسلم فسوق وقتاله كفر.",source:"صحيح البخاري (48)، وصحيح مسلم (64) عن ابن مسعود. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من حمل علينا السلاح فليس منا.",source:"صحيح البخاري (7070)، وصحيح مسلم (98) عن ابن عمر. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"كلكم راع وكلكم مسؤول عن رعيته.",source:"صحيح البخاري (893)، وصحيح مسلم (1829) عن ابن عمر. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"ما من عبد يسترعيه الله رعية يموت وهو غاش لرعيته إلا حرّم الله عليه الجنة.",source:"صحيح البخاري (7150)، وصحيح مسلم (142) عن معقل بن يسار. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"اللهم من ولي من أمر أمتي شيئًا فشق عليهم فاشقق عليه، ومن ولي فرفق بهم فارفق به.",source:"صحيح مسلم (1828) عن عائشة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من أطاعني فقد أطاع الله، ومن عصاني فقد عصى الله، ومن يطع الأمير فقد أطاعني.",source:"صحيح البخاري (7137)، وصحيح مسلم (1835) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"السمع والطاعة على المرء المسلم فيما أحب وكره ما لم يؤمر بمعصية، فإذا أُمر بمعصية فلا سمع ولا طاعة.",source:"صحيح البخاري (7144)، وصحيح مسلم (1839) عن ابن عمر. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إنما الطاعة في المعروف.",source:"صحيح البخاري (4340)، وصحيح مسلم (1840) عن علي. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من رأى منكم منكرًا فليغيّره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان.",source:"صحيح مسلم (49) عن أبي سعيد."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"والله لا يؤمن الذي لا يأمن جاره بوائقه.",source:"صحيح البخاري (6016) عن أبي شريح."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورّثه.",source:"صحيح البخاري (6014)، وصحيح مسلم (2624) عن عائشة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من أحب أن يُبسَط له في رزقه ويُنسَأ له في أثره فليصل رحمه.",source:"صحيح البخاري (2067)، وصحيح مسلم (2557) عن أنس. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"ليس الواصل بالمكافئ، ولكن الواصل الذي إذا قُطعت رحمه وصلها.",source:"صحيح البخاري (5991) عن عبد الله بن عمرو."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"رغم أنف من أدرك أبويه عند الكبر أحدهما أو كليهما ثم لم يدخل الجنة.",source:"صحيح مسلم (2551) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"ألا أنبئكم بأكبر الكبائر؟ الإشراك بالله، وعقوق الوالدين، وشهادة الزور.",source:"صحيح البخاري (2654)، وصحيح مسلم (87) عن أبي بكرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"كل مولود يولد على الفطرة، فأبواه يهوّدانه أو ينصّرانه أو يمجّسانه.",source:"صحيح البخاري (1358)، وصحيح مسلم (2658) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"رفع القلم عن ثلاثة: عن النائم حتى يستيقظ، وعن الصبي حتى يحتلم، وعن المجنون حتى يعقل.",source:"سنن أبي داود (4403) وسنن الترمذي (1423) عن علي."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إن الله تجاوز عن أمتي الخطأ والنسيان وما استُكرهوا عليه.",source:"سنن ابن ماجه (2045) عن ابن عباس، وصححه ابن حبان والحاكم."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إنما الأعمال بالخواتيم.",source:"صحيح البخاري (6607) عن سهل بن سعد."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إن أحدكم يُجمع خلقه في بطن أمه أربعين يومًا نطفة ثم يكون علقة ثم مضغة ثم يُبعث إليه الملك فيؤمر بكتب رزقه وأجله وعمله وشقي أو سعيد.",source:"صحيح البخاري (3208)، وصحيح مسلم (2643) عن ابن مسعود. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"آمنت بالقدر خيره وشره.",source:"صحيح مسلم (8) من حديث جبريل عن عمر."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"احفظ الله يحفظك، احفظ الله تجده تجاهك. إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله.",source:"سنن الترمذي (2516) عن ابن عباس وقال حسن صحيح."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الدعاء هو العبادة.",source:"سنن الترمذي (2969) عن النعمان بن بشير وقال حسن صحيح."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"يستجاب لأحدكم ما لم يعجل فيقول قد دعوت فلم يُستجب لي.",source:"صحيح البخاري (6340)، وصحيح مسلم (2735) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء.",source:"صحيح مسلم (482) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إن الله يبسط يده بالليل ليتوب مسيء النهار، ويبسط يده بالنهار ليتوب مسيء الليل حتى تطلع الشمس من مغربها.",source:"صحيح مسلم (2759) عن أبي موسى."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"والذي نفسي بيده لو لم تذنبوا لذهب الله بكم ولجاء بقوم يذنبون فيستغفرون الله فيغفر لهم.",source:"صحيح مسلم (2749) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الحياء من الإيمان.",source:"صحيح البخاري (24)، وصحيح مسلم (36) عن ابن عمر. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الحياء لا يأتي إلا بخير.",source:"صحيح البخاري (6117)، وصحيح مسلم (37) عن عمران بن حصين. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إذا لم تستح فاصنع ما شئت.",source:"صحيح البخاري (3484) عن أبي مسعود."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"أكمل المؤمنين إيمانًا أحسنهم خلقًا.",source:"سنن الترمذي (1162) عن أبي هريرة وقال حسن صحيح."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"ما من شيء أثقل في الميزان من حسن الخلق.",source:"سنن أبي داود (4799) عن أبي الدرداء."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إنما بُعثت لأتمم صالح الأخلاق.",source:"موطأ مالك، ومسند أحمد عن أبي هريرة وصححه ابن عبد البر."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"البر حسن الخلق، والإثم ما حاك في صدرك وكرهت أن يطلع عليه الناس.",source:"صحيح مسلم (2553) عن النواس بن سمعان."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من حسن إسلام المرء تركه ما لا يعنيه.",source:"موطأ مالك، وسنن الترمذي (2317) عن أبي هريرة وقال حسن."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"ازهد في الدنيا يحبك الله، وازهد فيما في أيدي الناس يحبك الناس.",source:"سنن ابن ماجه (4102) عن سهل بن سعد، وصححه النووي."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"الطهور شطر الإيمان والحمد لله تملأ الميزان وسبحان الله والحمد لله تملآن ما بين السماء والأرض.",source:"صحيح مسلم (223) عن أبي مالك الأشعري."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من صلى العشاء في جماعة فكأنما قام نصف الليل، ومن صلى الصبح في جماعة فكأنما قام الليل كله.",source:"صحيح مسلم (656) عن عثمان."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إن بين الرجل وبين الشرك والكفر ترك الصلاة.",source:"صحيح مسلم (82) عن جابر."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر.",source:"سنن الترمذي (2621) عن بريدة وقال حسن صحيح."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"أول ما يحاسب عليه العبد يوم القيامة الصلاة.",source:"سنن أبي داود (864) والترمذي (413) عن أبي هريرة."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من غدا إلى المسجد أو راح أعد الله له نزلًا في الجنة كلما غدا أو راح.",source:"صحيح البخاري (662)، وصحيح مسلم (669) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"صلاة الجماعة تفضل صلاة الفذ بسبع وعشرين درجة.",source:"صحيح البخاري (645)، وصحيح مسلم (650) عن ابن عمر. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إذا أقيمت الصلاة فلا تأتوها تسعون وأتوها تمشون عليكم السكينة، فما أدركتم فصلوا وما فاتكم فأتموا.",source:"صحيح البخاري (636)، وصحيح مسلم (602) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"من أدرك ركعة من الصلاة فقد أدرك الصلاة.",source:"صحيح البخاري (580)، وصحيح مسلم (607) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إنما جُعل الإمام ليُؤتم به، فإذا كبّر فكبّروا، وإذا ركع فاركعوا.",source:"صحيح البخاري (734)، وصحيح مسلم (411) عن أنس. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لا تُقبل صلاة بغير طهور، ولا صدقة من غلول.",source:"صحيح مسلم (224) عن ابن عمر."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"مفتاح الصلاة الطهور، وتحريمها التكبير، وتحليلها التسليم.",source:"سنن أبي داود (61) والترمذي (3) عن علي."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"إذا توضأ أحدكم فليجعل في أنفه ماء ثم لينتثر.",source:"صحيح البخاري (162)، وصحيح مسلم (237) عن أبي هريرة. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"ويل للأعقاب من النار.",source:"صحيح البخاري (60)، وصحيح مسلم (241) عن عبد الله بن عمرو. متفق عليه."},
{cat:"prophet",narrator:"عن النبي صلى الله عليه وسلم",text:"لا يزال أحدكم في صلاة ما دامت الصلاة تحبسه، لا يمنعه أن ينقلب إلى أهله إلا الصلاة.",source:"صحيح البخاري (659)، وصحيح مسلم (649) عن أبي هريرة. متفق عليه."},
{cat:"sahaba",narrator:"أبو بكر الصديق رضي الله عنه",text:"أيها الناس، إني وُلّيت عليكم ولست بخيركم، فإن أحسنت فأعينوني وإن أسأت فقوّموني. أطيعوني ما أطعت الله ورسوله، فإذا عصيت الله ورسوله فلا طاعة لي عليكم.",source:"سيرة ابن هشام، وتاريخ الطبري في خطبة البيعة."},
{cat:"sahaba",narrator:"أبو بكر الصديق رضي الله عنه",text:"والله لو منعوني عقالًا كانوا يؤدونه إلى رسول الله صلى الله عليه وسلم لقاتلتهم على منعه.",source:"صحيح البخاري (1399) و(6924)."},
{cat:"sahaba",narrator:"أبو بكر الصديق رضي الله عنه",text:"ما نفعني مال قط ما نفعني مال أبي بكر. قال أبو بكر: وهل أنا ومالي إلا لك يا رسول الله.",source:"سنن الترمذي (3661) وقال حسن."},
{cat:"sahaba",narrator:"عمر بن الخطاب رضي الله عنه",text:"حاسبوا أنفسكم قبل أن تحاسبوا، وزنوها قبل أن توزنوا.",source:"سنن الترمذي (2459) موقوفًا، وابن أبي الدنيا في محاسبة النفس."},
{cat:"sahaba",narrator:"عمر بن الخطاب رضي الله عنه",text:"لو كانت الدنيا كلها لي فافتديت بها من هول المطلع.",source:"الزهد لابن المبارك، وصفة الصفوة."},
{cat:"sahaba",narrator:"عمر بن الخطاب رضي الله عنه",text:"إن هذا الأمر لا يصلح إلا بالشدة التي لا جبرية فيها، واللين الذي لا وهن فيه.",source:"تاريخ الطبري، والبداية والنهاية."},
{cat:"sahaba",narrator:"عمر بن الخطاب رضي الله عنه",text:"نحن قوم أعزنا الله بالإسلام، فمهما ابتغينا العزة بغيره أذلنا الله.",source:"الحاكم والمستدرك، وابن سعد."},
{cat:"sahaba",narrator:"عمر بن الخطاب رضي الله عنه",text:"من كثر إخوانه كثر غرماؤه.",source:"الآداب الشرعية لابن مفلح عن عمر."},
{cat:"sahaba",narrator:"عمر بن الخطاب رضي الله عنه",text:"تفقهوا قبل أن تسودوا.",source:"صحيح البخاري تعليقًا في كتاب العلم."},
{cat:"sahaba",narrator:"عمر بن الخطاب رضي الله عنه",text:"لولا أن أسير في الأرض وأضرب في البلاد ما وليت عليهم.",source:"طبقات ابن سعد."},
{cat:"sahaba",narrator:"عثمان بن عفان رضي الله عنه",text:"وددت أن بيني وبين الجنة عقبة لا يقطعها إلا من غلب نفسه.",source:"حلية الأولياء لأبي نعيم."},
{cat:"sahaba",narrator:"عثمان بن عفان رضي الله عنه",text:"ما تمنيت ولا تغنيت ولا مسست ذكري بيميني منذ بايعت رسول الله صلى الله عليه وسلم.",source:"مسند أحمد، والزهد."},
{cat:"sahaba",narrator:"عثمان بن عفان رضي الله عنه",text:"لو أن قلوبنا طهرت ما شبعنا من كلام ربنا.",source:"حلية الأولياء."},
{cat:"sahaba",narrator:"علي بن أبي طالب رضي الله عنه",text:"قيمة كل امرئ ما يحسنه.",source:"البيان والتبيين للجاحظ، وعيون الأخبار."},
{cat:"sahaba",narrator:"علي بن أبي طالب رضي الله عنه",text:"الناس أعداء ما جهلوا.",source:"نهج البلاغة برواية الشريف، وأورده ابن عبد البر."},
{cat:"sahaba",narrator:"علي بن أبي طالب رضي الله عنه",text:"لا تكن عبد غيرك وقد جعلك الله حرًّا.",source:"وصية علي لابنه الحسن عند ابن أبي الدنيا."},
{cat:"sahaba",narrator:"علي بن أبي طالب رضي الله عنه",text:"من نصب نفسه للناس إمامًا فليبدأ بتعليم نفسه قبل تعليم غيره.",source:"نهج البلاغة، وأدب الدنيا والدين."},
{cat:"sahaba",narrator:"علي بن أبي طالب رضي الله عنه",text:"الفقه ثم المتجر، فإن من تاجر قبل أن يفقه ارتطم في الربا ثم ارتطم.",source:"موطأ مالك عن عمر بن الخطاب في المعنى، ورُوي عن علي في كتب الفقه."},
{cat:"sahaba",narrator:"عبد الله بن مسعود رضي الله عنه",text:"من كان مستنًّا فليستن بمن قد مات، فإن الحي لا تؤمن عليه الفتنة. أولئك أصحاب محمد صلى الله عليه وسلم كانوا أفضل هذه الأمة.",source:"جامع بيان العلم لابن عبد البر، والبغوي في شرح السنة."},
{cat:"sahaba",narrator:"عبد الله بن مسعود رضي الله عنه",text:"اتبعوا ولا تبتدعوا فقد كُفيتم.",source:"الدارمي في المقدمة، وابن وضاح في البدع."},
{cat:"sahaba",narrator:"عبد الله بن مسعود رضي الله عنه",text:"إنكم في زمان كثير فقهاؤه قليل خطباؤه، وسيأتي زمان قليل فقهاؤه كثير خطباؤه.",source:"موطأ مالك."},
{cat:"sahaba",narrator:"عبد الله بن مسعود رضي الله عنه",text:"ما ندمت على شيء ندمي على يوم غربت شمسه نقص فيه أجلي ولم يزد فيه عملي.",source:"حلية الأولياء."},
{cat:"sahaba",narrator:"عبد الله بن عباس رضي الله عنه",text:"تفكّروا في كل شيء ولا تفكروا في ذات الله.",source:"الأصبهاني في الترغيب، وابن أبي شيبة."},
{cat:"sahaba",narrator:"عبد الله بن عباس رضي الله عنه",text:"القرآن ذو وجوه، فاحملوه على أحسن وجوهه.",source:"تفسير الطبري مقدمة، وابن الأنباري."},
{cat:"sahaba",narrator:"عبد الله بن عباس رضي الله عنه",text:"الحجر الأسود يمين الله في الأرض، يصافح بها عباده.",source:"أحمد والحاكم، وفيه كلام، واشتهر في كتب المناسك."},
{cat:"sahaba",narrator:"عبد الله بن عمر رضي الله عنه",text:"كل بدعة ضلالة وإن رآها الناس حسنة.",source:"الدارمي، وابن وضاح، واللالكائي."},
{cat:"sahaba",narrator:"عبد الله بن عمر رضي الله عنه",text:"وددت أني لم أكن أسلمت إلا يوم أموت، لألحق بالنبي صلى الله عليه وسلم ولم أتلوث بشيء.",source:"طبقات ابن سعد."},
{cat:"sahaba",narrator:"عائشة رضي الله عنها",text:"ما خُيّر رسول الله صلى الله عليه وسلم بين أمرين إلا أخذ أيسرهما ما لم يكن إثمًا.",source:"صحيح البخاري (3560)، وصحيح مسلم (2327)."},
{cat:"sahaba",narrator:"عائشة رضي الله عنها",text:"كان خلقه القرآن.",source:"صحيح مسلم (746) في صلاة الليل."},
{cat:"sahaba",narrator:"عائشة رضي الله عنها",text:"ما رأيت أحدًا كان أشبه سمتًا وهديًا ودلًّا برسول الله صلى الله عليه وسلم من فاطمة.",source:"سنن أبي داود (5217) والترمذي."},
{cat:"sahaba",narrator:"أبو هريرة رضي الله عنه",text:"جزّأت الليل ثلاثة أجزاء: ثلثًا أصلي، وثلثًا أنام، وثلثًا أدرس فيه حديث رسول الله صلى الله عليه وسلم.",source:"سنن الدارمي."},
{cat:"sahaba",narrator:"أبو هريرة رضي الله عنه",text:"حفظت من رسول الله صلى الله عليه وسلم وعاءين، فأما أحدهما فبثثته، وأما الآخر فلو بثثته قُطع هذا البلعوم.",source:"صحيح البخاري (120)."},
{cat:"sahaba",narrator:"معاذ بن جبل رضي الله عنه",text:"العلم إمام والعمل تابعه.",source:"حلية الأولياء، وجامع بيان العلم."},
{cat:"sahaba",narrator:"أبو الدرداء رضي الله عنه",text:"ما أنا بالذي أحدثكم أني أعلمكم، ولكني أعلمكم أن أعلمكم بالله أشدكم له خشية.",source:"حلية الأولياء."},
{cat:"sahaba",narrator:"أبو الدرداء رضي الله عنه",text:"تفقهوا قبل أن تسودوا، ولن تسودوا حتى تتفقهوا.",source:"جامع بيان العلم لابن عبد البر."},
{cat:"sahaba",narrator:"أبو الدرداء رضي الله عنه",text:"إن أخوف ما أخاف إذا وقفت على الحساب أن يقال لي: قد علمت فماذا عملت؟",source:"حلية الأولياء."},
{cat:"sahaba",narrator:"حذيفة بن اليمان رضي الله عنه",text:"كان الناس يسألون رسول الله صلى الله عليه وسلم عن الخير، وكنت أسأله عن الشر مخافة أن يدركني.",source:"صحيح البخاري (3606)، وصحيح مسلم (1847)."},
{cat:"sahaba",narrator:"حذيفة بن اليمان رضي الله عنه",text:"إن الضلالة حق الضلالة أن تعرف ما كنت تنكر، وتنكر ما كنت تعرف.",source:"ابن وضاح في البدع، والدارمي."},
{cat:"sahaba",narrator:"أبو ذر الغفاري رضي الله عنه",text:"إني لأرى الرجل فيأبى فؤادي أن أكلمه حتى أعلم أفي قلبه للإسلام ودّ.",source:"حلية الأولياء."},
{cat:"sahaba",narrator:"أبو ذر الغفاري رضي الله عنه",text:"يا ابن آدم، عملك كله في ثلاث: طرفاه لك، ووسطه لغيرك. فأمسك طرفيه يسلم لك وسطه.",source:"ابن المبارك في الزهد."},
{cat:"sahaba",narrator:"سلمان الفارسي رضي الله عنه",text:"إن مثل القلب مثل ريشة بأرض فلاة تقلبها الرياح ظهرًا لبطن.",source:"ابن أبي شيبة، وأحمد في المعنى مرفوعًا عند ابن ماجه."},
{cat:"sahaba",narrator:"سلمان الفارسي رضي الله عنه",text:"أُعطيت أربعًا: رفعت لي الأرض حتى كأني أنظر إلى مشارقها ومغاربها...",source:"جزء من حديث صحيح مسلم في خصائص الأمة، وسلمان من رواته في السير."},
{cat:"sahaba",narrator:"أبيّ بن كعب رضي الله عنه",text:"عليكم بالسبيل والسنة، فإنه ليس من عبد على سبيل وسنة ذكر الرحمن ففاضت عيناه من خشية الله فيعذبه.",source:"اللالكائي في شرح أصول الاعتقاد."},
{cat:"sahaba",narrator:"عمار بن ياسر رضي الله عنه",text:"ثلاث من كن فيه فقد استكمل الإيمان: الإنفاق من الإقتار، وبذل السلام للعالم، والإنصاف من نفسه.",source:"البخاري تعليقًا في الإيمان، موقوفًا على عمار."},
{cat:"sahaba",narrator:"سعد بن أبي وقاص رضي الله عنه",text:"إني لأول العرب رمى بسهم في سبيل الله.",source:"صحيح البخاري (3728)، وصحيح مسلم (2966)."},
{cat:"sahaba",narrator:"الزبير بن العوام رضي الله عنه",text:"من استطاع منكم أن يكون له خبيء من عمل صالح فليفعل.",source:"ابن المبارك في الزهد."},
{cat:"sahaba",narrator:"عبد الرحمن بن عوف رضي الله عنه",text:"أُتيت اليوم بطعام فبكيت، فقلت: رسول الله صلى الله عليه وسلم مات ولم يشبع من خبز الشعير.",source:"صحيح البخاري (5418) في المعنى عن أنس، وعن عبد الرحمن في السير."},
{cat:"sahaba",narrator:"أبو عبيدة بن الجراح رضي الله عنه",text:"إني سمعت رسول الله صلى الله عليه وسلم يقول: إن هذا الحي من مضر لا يزالون في خير ما اتقوا الله.",source:"ابن سعد في الطبقات."},
{cat:"sahaba",narrator:"أبو موسى الأشعري رضي الله عنه",text:"مثل الذي يذكر ربه والذي لا يذكر مثل الحي والميت.",source:"صحيح البخاري (6407) مرفوعًا عن أبي موسى."},
{cat:"sahaba",narrator:"جابر بن عبد الله رضي الله عنه",text:"كنا مع رسول الله صلى الله عليه وسلم في سفر فكسعت ناقة رجل أعرابي فقيل: عليك حدها. فقال النبي صلى الله عليه وسلم: دعها فإنها ملعونة.",source:"صحيح مسلم في المعنى، وجابر من رواة المغازي."},
{cat:"sahaba",narrator:"أنس بن مالك رضي الله عنه",text:"خدمت النبي صلى الله عليه وسلم عشر سنين، فما قال لي أفٍّ قط.",source:"صحيح البخاري (6038)، وصحيح مسلم (2309)."},
{cat:"sahaba",narrator:"البراء بن عازب رضي الله عنه",text:"كان رسول الله صلى الله عليه وسلم مربوعًا بعيد ما بين المنكبين، له شعر يبلغ شحمة أذنيه.",source:"صحيح البخاري (3551)، وصحيح مسلم (2337)."},
{cat:"sahaba",narrator:"زيد بن ثابت رضي الله عنه",text:"كنت أكتب الوحي لرسول الله صلى الله عليه وسلم، وإنه ليُنزل عليه وإنه ليُعرَف منه، ثم يُسرَّى عنه فأكتب وهو يُمليه علي.",source:"مسند أحمد، والمستدرك."},
{cat:"sahaba",narrator:"أسامة بن زيد رضي الله عنه",text:"بعثني رسول الله صلى الله عليه وسلم في سرية فقتلت رجلًا قال لا إله إلا الله، فقال: أقتلته بعد ما قال لا إله إلا الله؟",source:"صحيح البخاري (4269)، وصحيح مسلم (96)."},
{cat:"sahaba",narrator:"خباب بن الأرت رضي الله عنه",text:"شكونا إلى رسول الله صلى الله عليه وسلم وهو متوسد بردة في ظل الكعبة فقلنا: ألا تستنصر لنا؟ فقال: قد كان من قبلكم يُمشط بأمشاط الحديد.",source:"صحيح البخاري (3852)."},
{cat:"sahaba",narrator:"صهيب الرومي رضي الله عنه",text:"يا أبا يحيى، ربح البيع. قال: وما ذاك؟ قال: نزلت فيك: ومن الناس من يشري نفسه ابتغاء مرضات الله.",source:"مستدرك الحاكم، وابن سعد، في هجرته."},
{cat:"sahaba",narrator:"بلال بن رباح رضي الله عنه",text:"لولا أن رسول الله صلى الله عليه وسلم أمرني بالأذان ما أذّنت.",source:"ابن سعد، والسير بعد وفاة النبي صلى الله عليه وسلم."},
{cat:"sahaba",narrator:"أم سلمة رضي الله عنها",text:"نهى رسول الله صلى الله عليه وسلم أن نمتشط كل يوم، أو نتطيب إلا لزوجها.",source:"سنن النسائي في الزينة."},
{cat:"sahaba",narrator:"أسماء بنت أبي بكر رضي الله عنها",text:"أنفق ولا تحصي فيحصي الله عليك، ولا توعي فيوعي الله عليك.",source:"صحيح البخاري (1434)، وصحيح مسلم (1029) مرفوعًا إليها."},
{cat:"sahaba",narrator:"فاطمة رضي الله عنها",text:"ما عهد إليّ رسول الله صلى الله عليه وسلم سرًّا دون الناس غير أنه قال لي: إن جبريل كان يعارضني القرآن كل سنة مرة وإنه عارضني العام مرتين، ولا أراني إلا ميت في عامي هذا.",source:"صحيح البخاري (3624)، وصحيح مسلم (2450)."},
{cat:"sahaba",narrator:"الحسن بن علي رضي الله عنه",text:"إنما تصلح الدنيا بخصال ثلاث: الأمر بالمعروف، والنهي عن المنكر، وبذل الندى.",source:"حلية الأولياء، وابن عساكر."},
{cat:"sahaba",narrator:"الحسين بن علي رضي الله عنه",text:"من طلب رضا الله بسخط الناس كفاه الله، ومن طلب رضا الناس بسخط الله وكله الله إلى الناس.",source:"الترمذي (2414) مرفوعًا، ويُروى من كلام الحسين في التواريخ."},
{cat:"sahaba",narrator:"عبد الله بن سلام رضي الله عنه",text:"إن أحق ما قيل في القرآن أن يُتعلَّم.",source:"ابن سعد."},
{cat:"sahaba",narrator:"تميم الداري رضي الله عنه",text:"أول من أسرج السراج في المسجد تميم الداري.",source:"ابن سعد، والبخاري تعليقًا."},
{cat:"sahaba",narrator:"عبادة بن الصامت رضي الله عنه",text:"بايعنا رسول الله صلى الله عليه وسلم على السمع والطاعة في المنشط والمكره.",source:"صحيح البخاري (7199)، وصحيح مسلم (1709)."},
{cat:"sahaba",narrator:"أبو سعيد الخدري رضي الله عنه",text:"كان رسول الله صلى الله عليه وسلم أشد حياء من العذراء في خدرها.",source:"صحيح البخاري (3562)، وصحيح مسلم (2320)."},
{cat:"sahaba",narrator:"سهل بن سعد رضي الله عنه",text:"ما أكل رسول الله صلى الله عليه وسلم على خوان قط، ولا خُبز له مرقق.",source:"صحيح البخاري (5413)."},
{cat:"sahaba",narrator:"النعمان بن بشير رضي الله عنه",text:"الحلال بيّن والحرام بيّن سمعت ذلك من رسول الله صلى الله عليه وسلم.",source:"صحيح البخاري (52)، وصحيح مسلم (1599)."},
{cat:"sahaba",narrator:"المغيرة بن شعبة رضي الله عنه",text:"كان النبي صلى الله عليه وسلم يقوم حتى ترم قدماه، فيقال له: قد غفر الله لك. فيقول: أفلا أكون عبدًا شكورًا.",source:"صحيح البخاري (1130)، وصحيح مسلم (2819)."},
{cat:"sahaba",narrator:"أبو بكرة رضي الله عنه",text:"إذا التقى المسلمان بسيفيهما فالقاتل والمقتول في النار.",source:"صحيح البخاري (31)، وصحيح مسلم (2888)."},
{cat:"sahaba",narrator:"عمران بن حصين رضي الله عنه",text:"حدثنا رسول الله صلى الله عليه وسلم بأحاديث وددنا أن النبي صلى الله عليه وسلم لم يفارقنا حتى نسأله عنها.",source:"مسند أحمد."},
{cat:"sahaba",narrator:"سمرة بن جندب رضي الله عنه",text:"كان رسول الله صلى الله عليه وسلم مما يكثر أن يقول لأصحابه: هل رأى أحد منكم من رؤيا؟",source:"صحيح البخاري (7047)."},
{cat:"sahaba",narrator:"جابر بن سمرة رضي الله عنه",text:"كان رسول الله صلى الله عليه وسلم لا يطيل الموعظة يوم الجمعة، إنما هن كلمات يسيرات.",source:"صحيح مسلم (869) في المعنى، وأبو داود."},
{cat:"sahaba",narrator:"عبد الله بن الزبير رضي الله عنه",text:"ما ندمت على سكوت قط.",source:"ابن عساكر، وحلية الأولياء."},
{cat:"sahaba",narrator:"معاوية بن أبي سفيان رضي الله عنه",text:"لا أضع سيفي حيث يكفيني سوطي، ولا أضع سوطي حيث يكفيني لساني.",source:"تاريخ الطبري، والبداية والنهاية."},
{cat:"sahaba",narrator:"عمرو بن العاص رضي الله عنه",text:"ما رأيت أحدًا أحضر ذهنًا ولا أكرم مجلسًا من رسول الله صلى الله عليه وسلم.",source:"ابن سعد."},
{cat:"sahaba",narrator:"أبو أيوب الأنصاري رضي الله عنه",text:"نزل عليّ رسول الله صلى الله عليه وسلم في بيتي لما قدم المدينة.",source:"صحيح مسلم (2053) وغيره."},
{cat:"sahaba",narrator:"سعد بن معاذ رضي الله عنه",text:"لقد حكمت فيهم بحكم الملك. قاله النبي صلى الله عليه وسلم لسعد في بني قريظة.",source:"صحيح البخاري (3043)، وصحيح مسلم (1768)."},
{cat:"sahaba",narrator:"أسيد بن حضير رضي الله عنه",text:"ما هي بأول بركتكم يا آل أبي بكر. قاله لما نزلت آية التيمم.",source:"صحيح البخاري (334)، وصحيح مسلم (367)."},
{cat:"sahaba",narrator:"خزيمة بن ثابت رضي الله عنه",text:"من شهد له خزيمة فحسبه. جعل النبي صلى الله عليه وسلم شهادته بشهادة رجلين.",source:"سنن أبي داود (3607)، والنسائي."},
{cat:"sahaba",narrator:"أبو طلحة الأنصاري رضي الله عنه",text:"إن أحب أموالي إليّ بيرحاء، وإنها صدقة لله.",source:"صحيح البخاري (1461)، وصحيح مسلم (998)."},
{cat:"sahaba",narrator:"كعب بن مالك رضي الله عنه",text:"تخلفت عن تبوك بغير نفاق فهجرنا خمسين ليلة حتى نزلت توبتنا.",source:"صحيح البخاري (4418)، وصحيح مسلم (2769)."},
{cat:"sahaba",narrator:"هلال بن أمية رضي الله عنه",text:"أحد الثلاثة الذين خلّفوا فتيب عليهم مع كعب ومرارة.",source:"صحيح البخاري ومسلم في حديث كعب."},
{cat:"sahaba",narrator:"مرارة بن الربيع رضي الله عنه",text:"أحد الثلاثة الذين خلّفوا عن تبوك بغير عذر نفاق.",source:"صحيح البخاري ومسلم في حديث كعب."},
{cat:"sahaba",narrator:"زيد بن أرقم رضي الله عنه",text:"كنت مع النبي صلى الله عليه وسلم فسمع عبد الله بن أبي يقول: لئن رجعنا إلى المدينة ليخرجن الأعز منها الأذل، فأخبرت النبي صلى الله عليه وسلم فنزلت سورة المنافقون.",source:"صحيح البخاري (4900)، وصحيح مسلم (2772)."},
{cat:"sahaba",narrator:"البراء بن مالك رضي الله عنه",text:"إن أخي أنس بن النضر غاب عن بدر فقال: لئن أشهدني الله قتالًا ليرين الله ما أصنع. فقتل يوم أحد وبه بضع وسبعون جرحًا.",source:"صحيح البخاري (2805)."},
{cat:"sahaba",narrator:"أنس بن النضر رضي الله عنه",text:"لئن أشهدني الله قتال المشركين ليرين الله ما أصنع. صدق الله فقاتل حتى قتل.",source:"صحيح البخاري (2805) عن أنس."},
{cat:"sahaba",narrator:"سعد بن الربيع رضي الله عنه",text:"آخى النبي صلى الله عليه وسلم بينه وبين عبد الرحمن بن عوف فعرض عليه شطر ماله فنزل عبد الرحمن عن ذلك واتجر.",source:"صحيح البخاري (2048)."},
{cat:"sahaba",narrator:"مصعب بن عمير رضي الله عنه",text:"قُتل يوم أحد فلم نجد ما نكفنه إلا بردة إذا غطينا بها رأسه بدت رجلاه.",source:"صحيح البخاري (1276)."},
{cat:"sahaba",narrator:"حمزة بن عبد المطلب رضي الله عنه",text:"سيد الشهداء يوم أحد، قتله وحشي.",source:"صحيح البخاري (4072) في مقتله."},
{cat:"sahaba",narrator:"جعفر بن أبي طالب رضي الله عنه",text:"وجدنا ما في جسده يوم مؤتة بضعًا وتسعين من بين طعنة وضربة.",source:"صحيح البخاري (4262) في أمراء مؤتة."},
{cat:"sahaba",narrator:"عبد الله بن رواحة رضي الله عنه",text:"ثالث أمراء مؤتة، قُتل بعد زيد وجعفر.",source:"صحيح البخاري (4262)."},
{cat:"sahaba",narrator:"زيد بن حارثة رضي الله عنه",text:"الحب ابن الحب، أول أمراء مؤتة.",source:"صحيح البخاري (3732) و(4262)."},
{cat:"sahaba",narrator:"خالد بن الوليد رضي الله عنه",text:"نعم عبد الله خالد بن الوليد سيف من سيوف الله. قاله النبي صلى الله عليه وسلم.",source:"سنن الترمذي (3846) وقال حسن، والبخاري (4262) في أخذه الراية."},
{cat:"sahaba",narrator:"عكرمة بن أبي جهل رضي الله عنه",text:"أسلم يوم الفتح وحسن إسلامه وقاتل يوم اليرموك حتى استُشهد.",source:"ابن سعد، والبداية والنهاية."},
{cat:"sahaba",narrator:"عمير بن وهب رضي الله عنه",text:"أسلم بعد أن جاء المدينة ليقتل النبي صلى الله عليه وسلم فشرح الله صدره.",source:"سيرة ابن هشام."},
{cat:"sahaba",narrator:"أبو سفيان بن حرب رضي الله عنه",text:"أسلم يوم الفتح وقال النبي صلى الله عليه وسلم: من دخل دار أبي سفيان فهو آمن.",source:"صحيح مسلم (1780)، وسيرة ابن هشام."},
{cat:"sahaba",narrator:"هند بنت عتبة رضي الله عنها",text:"بايعت النبي صلى الله عليه وسلم يوم الفتح على ألا تشرك ولا تسرق ولا تزني.",source:"صحيح البخاري (7214) عن عائشة في بيعة النساء."},
{cat:"sahaba",narrator:"أم عمارة نسيبة بنت كعب رضي الله عنها",text:"قاتلت يوم أحد دون النبي صلى الله عليه وسلم حتى جُرحت.",source:"سيرة ابن هشام، وابن سعد."},
{cat:"sahaba",narrator:"الربيع بنت معوذ رضي الله عنها",text:"كنا نغزو مع النبي صلى الله عليه وسلم فنسقي القوم ونخدمهم ونرد القتلى والجرحى إلى المدينة.",source:"صحيح البخاري (2883)."},
{cat:"tabieen",narrator:"الحسن البصري رحمه الله",text:"يا ابن آدم، إنك ناظر إلى عملك يوزن خيره وشره، فلا تحقرن من المعروف شيئًا.",source:"حلية الأولياء، وسير أعلام النبلاء."},
{cat:"tabieen",narrator:"الحسن البصري رحمه الله",text:"ما من يوم يفتح إلا وينادي: يا ابن آدم، أنا خلق جديد، وعلى عملك شهيد، فاغتنمني فإني لا أعود إلى يوم القيامة.",source:"ابن أبي الدنيا في قصر الأمل."},
{cat:"tabieen",narrator:"الحسن البصري رحمه الله",text:"ابن آدم، إنما أنت أيام، كلما ذهب يوم ذهب بعضك.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"الحسن البصري رحمه الله",text:"فضح الموت الدنيا فما أبقى لذي لب فرحًا.",source:"الزهد لابن المبارك."},
{cat:"tabieen",narrator:"الحسن البصري رحمه الله",text:"إن قومًا ألهتهم أماني المغفرة حتى خرجوا من الدنيا ولا حسنة لهم.",source:"ابن أبي الدنيا في قصر الأمل."},
{cat:"tabieen",narrator:"الحسن البصري رحمه الله",text:"يا ابن آدم، بع دنياك بآخرتك تربحهما جميعًا، ولا تبع آخرتك بدنياك فتخسرهما جميعًا.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"الحسن البصري رحمه الله",text:"المؤمن في الدنيا كالغريب لا يجزع من ذلها ولا ينافس في عزها.",source:"الزهد لأحمد."},
{cat:"tabieen",narrator:"سعيد بن المسيب رحمه الله",text:"ما بقي أحد أعلم بقضاء رسول الله صلى الله عليه وسلم وقضاء أبي بكر وعمر مني.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"سعيد بن المسيب رحمه الله",text:"إن الدنيا نذلة، وهي إلى أهلها نذلة، وكل ما فيها إلى نذالة.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"سعيد بن المسيب رحمه الله",text:"لا خير فيمن لا يريد جمع المال من حله، يكف به وجهه عن الناس ويصل رحمه.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"عمر بن عبد العزيز رحمه الله",text:"إن الليل والنهار يعملان فيك فاعمل فيهما.",source:"سيرة عمر بن عبد العزيز لابن عبد الحكم."},
{cat:"tabieen",narrator:"عمر بن عبد العزيز رحمه الله",text:"أما بعد فإنكم إن أطعتم الله نفعكم وإن عصيتموه لم يضر إلا أنفسكم.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"عمر بن عبد العزيز رحمه الله",text:"الإيمان قيود وحصون، من جعلها وراء ظهره أُتي من الأمن، ومن جعلها أمامه أُتي من الخوف.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"عمر بن عبد العزيز رحمه الله",text:"لو كان لي دعوة مستجابة لجعلتها في صلاح السلطان، فإن بصلاحه صلاح العباد والبلاد.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"عمر بن عبد العزيز رحمه الله",text:"التقوى ليست بالقيام الليل وصيام النهار والتخليط فيما بين ذلك، ولكن التقوى أداء ما افترض الله وترك ما حرّم الله.",source:"ابن أبي الدنيا."},
{cat:"tabieen",narrator:"محمد بن سيرين رحمه الله",text:"إن هذا العلم دين فانظروا عمن تأخذون دينكم.",source:"مقدمة صحيح مسلم."},
{cat:"tabieen",narrator:"محمد بن سيرين رحمه الله",text:"ما رأيت على رجل شيئًا فكرهته ثم رأيته عليه إلا وعظني.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"عطاء بن أبي رباح رحمه الله",text:"إن الرجل ليحدثني بالحديث فأنصت له كأني لم أسمعه وقد سمعته قبل أن يولد.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"مجاهد بن جبر رحمه الله",text:"عرضت القرآن على ابن عباس ثلاث عرضات أقف عند كل آية أسأله فيم نزلت وكيف كانت.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"مجاهد بن جبر رحمه الله",text:"أفضل العبادة الرأي الحسن. يعني الفقه في الدين.",source:"جامع بيان العلم."},
{cat:"tabieen",narrator:"علقمة بن قيس النخعي رحمه الله",text:"أطيلوا كرّ الحديث لا يدرس.",source:"جامع بيان العلم."},
{cat:"tabieen",narrator:"الأسود بن يزيد النخعي رحمه الله",text:"كان يجهد نفسه في الحج والعمرة حتى يعاد من الجهد.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"إبراهيم النخعي رحمه الله",text:"كانوا يكرهون إذا اجتمعوا أن يخرج الرجل أحسن حديثه أو أحسن ما عنده.",source:"جامع بيان العلم."},
{cat:"tabieen",narrator:"إبراهيم النخعي رحمه الله",text:"ما كل ما يُعلم يُقال.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"عامر الشعبي رحمه الله",text:"ما رأيت أحدًا أطلب للعلم في أفق من الآفاق من ابن عباس.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"عامر الشعبي رحمه الله",text:"إنما كان يطلب هذا العلم من اجتمعت فيه خصلتان: العقل والنسك، فإن كان ناسكًا ولم يكن عاقلًا قال: هذا أجن، وإن كان عاقلًا ولم يكن ناسكًا قال: هذا يضربني.",source:"جامع بيان العلم."},
{cat:"tabieen",narrator:"طاوس بن كيسان رحمه الله",text:"ما حمل رجل وسادة إلى عالم إلا حمل عنه علمًا، ولا حملها إلى سلطان إلا حمل عنه ذلًّا.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"وهب بن منبه رحمه الله",text:"الإيمان عريان، ولباسه التقوى، وزينته الحياء، وماله الفقه.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"الربيع بن خثيم رحمه الله",text:"ما العلم إلا العمل به.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"الربيع بن خثيم رحمه الله",text:"ما سبقهم أبو بكر بكثرة صلاة ولا صيام، ولكن بشيء وقر في قلبه.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"مسروق بن الأجدع رحمه الله",text:"بحسب المرء من العلم أن يخشى الله، وبحسبه من الجهل أن يعجب بعلمه.",source:"جامع بيان العلم."},
{cat:"tabieen",narrator:"شريح القاضي رحمه الله",text:"إني لأصاب بالمصيبة فأحمد الله عليها أربع مرات: أحمد إذ لم تكن أعظم، وأحمد إذ رزقت الصبر، وأحمد إذ وفقت للاسترجاع، وأحمد إذ لم تجعل في ديني.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"أبو العالية الرياحي رحمه الله",text:"عليكم بالأمر الأول الذي كانوا عليه قبل أن يتفرقوا.",source:"اللالكائي."},
{cat:"tabieen",narrator:"مطرف بن عبد الله رحمه الله",text:"لأن أعافى فأشكر أحب إلي من أن أبتلى فأصبر.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"مطرف بن عبد الله رحمه الله",text:"إن هذا الموت قد فضح الدنيا فلم يدع لذي لب فرحًا.",source:"الزهد لابن المبارك."},
{cat:"tabieen",narrator:"بكر بن عبد الله المزني رحمه الله",text:"إذا رأيت من هو أكبر منك فقل: سبقني إلى الإيمان والعمل. وإذا رأيت من هو أصغر فقل: سبقته إلى الذنوب.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"مالك بن دينار رحمه الله",text:"خرجت من المربد فما لقيت أحدًا إلا ظننته خيرًا مني.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"مالك بن دينار رحمه الله",text:"إن الصديقين إذا قُرئ عليهم القرآن طربت قلوبهم إلى الآخرة.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"ثابت البناني رحمه الله",text:"ما تركت في المسجد سارية إلا وقمت إليها.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"قتادة بن دعامة رحمه الله",text:"ما أعدت للموت شيئًا من المال، أعددت شهادة أن لا إله إلا الله.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"سعيد بن جبير رحمه الله",text:"وددت أن الناس أخذوا ما في صدري حتى لا أُسأل.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"سعيد بن جبير رحمه الله",text:"التوبة ما لم يغرغر.",source:"تفسير ابن كثير في آية التوبة."},
{cat:"tabieen",narrator:"عكرمة مولى ابن عباس رحمه الله",text:"ما من آية في القرآن إلا وأنا أعلم فيم نزلت.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"نافع مولى ابن عمر رحمه الله",text:"صحبت ابن عمر ثلاثين سنة فما سمعته يعيب طعامًا قط.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"سالم بن عبد الله بن عمر رحمه الله",text:"كان أشبه ولد عمر بعمر.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"القاسم بن محمد بن أبي بكر رحمه الله",text:"لأن يعيش الرجل جاهلًا بعد أن يعلم حق الله عليه خير له من أن يقول ما لا يعلم.",source:"جامع بيان العلم."},
{cat:"tabieen",narrator:"عروة بن الزبير رحمه الله",text:"إنما أخذنا العلم من فقهاء المدينة السبعة.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"أبو بكر بن عبد الرحمن بن الحارث رحمه الله",text:"أحد فقهاء المدينة السبعة، وكان يقال له راهب قريش.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"سليمان بن يسار رحمه الله",text:"كان إذا سئل عن المسألة قال: أعيذكم بالله أن تقولوا برأينا.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"خارجة بن زيد بن ثابت رحمه الله",text:"كان يفتي مع فقهاء المدينة في زمن التابعين.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"عبيد الله بن عبد الله بن عتبة رحمه الله",text:"لا أحسب أحدًا اليوم أعلم بما مضى مني.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"رجاء بن حيوة رحمه الله",text:"هو الذي أشار بسليمان على الوليد في ولاية عمر بن عبد العزيز.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"مكحول الشامي رحمه الله",text:"ما استودعت صدري شيئًا قط فنسيته.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"الأوزاعي رحمه الله",text:"اصبر على السنة، وقف حيث وقف القوم، وقل بما قالوا، وكف عما كفوا عنه.",source:"اللالكائي في شرح أصول الاعتقاد."},
{cat:"tabieen",narrator:"محمد بن المنكدر رحمه الله",text:"كابدت نفسي أربعين سنة حتى استقامت.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"صفوان بن سليم رحمه الله",text:"كان يُقال إنه لم يضع جنبه على الأرض أربعين سنة.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"أبو حازم سلمة بن دينار رحمه الله",text:"الدنيا قرية قد تخرب أكثرها، والآخرة قرية لم تعمر بعد.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"أبو حازم سلمة بن دينار رحمه الله",text:"إن عُرضت الدنيا عليك فخذها، وإن أعرضت عنك فلا تطلبها.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"يونس بن عبيد رحمه الله",text:"ما استخف رجل بحق أحد إلا استخف بحق الله.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"أيوب السختياني رحمه الله",text:"إذا ذكرت الصالحين فكن منهم.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"أيوب السختياني رحمه الله",text:"ما ازداد صاحب بدعة اجتهادًا إلا ازداد من الله بعدًا.",source:"اللالكائي."},
{cat:"tabieen",narrator:"يونس بن جبير رحمه الله",text:"ما رأيت أحدًا قط إلا أنا له ناصح.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"محمد بن واسع رحمه الله",text:"لقد أدركت رجالًا كان الرجل يكون رأسًا من الرؤوس وما يُشعر به.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"الحسن بن أبي الحسن رحمه الله",text:"يا ابن آدم، عملك عملك، فإنما هو لحمك ودمك، فانظر من تطاعمه.",source:"الزهد لابن المبارك."},
{cat:"tabieen",narrator:"غيلان بن جرير رحمه الله",text:"ما نازلت أحدًا في ورع فوجدته إلا دون ما في نفسي حتى نازلت محمد بن واسع.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"أبو قلابة الجرمي رحمه الله",text:"لا تجالسوا أهل الأهواء ولا تجادلوهم فإني لا آمن أن يغمسوكم في ضلالتهم.",source:"اللالكائي."},
{cat:"tabieen",narrator:"محمد بن كعب القرظي رحمه الله",text:"إذا أراد الله بعبد خيرًا جعل فيه ثلاث خصال: الفقه في الدين، والزهد في الدنيا، والبصيرة في عيوبه.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"زيد بن أسلم رحمه الله",text:"كان يفسر القرآن برأي حسن، وأخذ عنه مالك.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"ربيعة الرأي رحمه الله",text:"بل بعض الرأي خير من بعض، والعلم هو الأصل.",source:"جامع بيان العلم."},
{cat:"tabieen",narrator:"ربيعة الرأي رحمه الله",text:"قال لمالك وهو غلام: ما السفه إلا السفه في الدين.",source:"ترتيب المدارك."},
{cat:"tabieen",narrator:"أبو الزناد عبد الله بن ذكوان رحمه الله",text:"أدركت بالمدينة مئة كلهم مأمون ما يؤخذ عنهم الحديث، يقال: ليس من أهله.",source:"مقدمة صحيح مسلم."},
{cat:"tabieen",narrator:"هشام بن عروة رحمه الله",text:"كان يقول: كان أبي يقول لي: يا بني لا تكتب العلم حتى تفهمه.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"الزهري محمد بن شهاب رحمه الله",text:"ما استودعت قلبي علمًا فنسيته.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"الزهري محمد بن شهاب رحمه الله",text:"العلم خزائن ومفتاحها السؤال.",source:"جامع بيان العلم."},
{cat:"tabieen",narrator:"كهمس بن الحسن رحمه الله",text:"غفلت عن ليلة فنظرت فإذا هي مثقلة عليّ في القبر.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"إبراهيم التيمي رحمه الله",text:"ما عرضت قولي على عملي إلا خشيت أن أكون مكذبًا.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"عمرو بن شرحبيل رحمه الله",text:"لأن أكون رميمًا أحب إلي من أن أكون قاضيًا.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"أبو وائل شقيق بن سلمة رحمه الله",text:"صحبت ابن مسعود فما سمعته يعيب طعامًا قط.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"زر بن حبيش رحمه الله",text:"ما من آية إلا وقد قرأتها على عبد الله بن مسعود.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"عبيدة السلماني رحمه الله",text:"أسلم قبل وفاة النبي صلى الله عليه وسلم بسنتين ولم يره، وهو من كبار التابعين.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"الحارث بن قيس رحمه الله",text:"إذا وجدت من قلبك قسوة فجالس أهل الذكر.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"أبو مسلم الخولاني رحمه الله",text:"لو رأيت الجنة والنار لما ازددت اجتهادًا.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"أبو مسلم الخولاني رحمه الله",text:"الإخوان في الله أسرع ائتلافًا من المياه في الأنهار.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"أويس القرني رحمه الله",text:"عليك بنفسك فمن معها.",source:"حلية الأولياء، وصحيح مسلم في ذكره."},
{cat:"tabieen",narrator:"أويس القرني رحمه الله",text:"ما من ساعة تمر بابن آدم لا يذكر الله فيها إلا حسرة يوم القيامة.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"صلة بن أشيم رحمه الله",text:"اركع لله ركعتين في سواد هذا الليل لشدة سواد ذلك اليوم.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"عامر بن عبد قيس رحمه الله",text:"ما أسفت على شيء من الدنيا إلا أني لم أكن أملأ عيني من السماء.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"هرم بن حيان رحمه الله",text:"ما أصبحت في يوم قط إلا ظننت أني لا أمسي، ولا أمسيت إلا ظننت أني لا أصبح.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"الأحنف بن قيس رحمه الله",text:"وجدت الحلم أنصر لي من الرجال.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"الأحنف بن قيس رحمه الله",text:"لا أخاصم إلا من أرجو نيله أو أخاف سله.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"محمد بن علي الباقر رحمه الله",text:"ما دخل قلب امرئ شيء من الكبر إلا نقص من عقله مثل ما دخل منه.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"علي بن الحسين زين العابدين رحمه الله",text:"اللهم إني أعوذ بك أن تحسن في لوائح العيون علانيتي وتقبح في خفيات العيون سريرتي.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"جعفر بن محمد الصادق رحمه الله",text:"لا يتم المعروف إلا بثلاثة: تعجيله، وتصغيره، وستره.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"القاسم بن مخيمرة رحمه الله",text:"ما تكلمت بكلمة منذ عشرين سنة إلا وأنا أخطمها وأزمها غير مرة.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"منصور بن زاذان رحمه الله",text:"كان يختم القرآن بين المغرب والعشاء.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"عاصم بن بهدلة رحمه الله",text:"من قرأ القرآن يقوم به آناء الليل والنهار يحل حلاله ويحرم حرامه.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"يحيى بن وثاب رحمه الله",text:"إمام أهل الكوفة في القراءة في زمنه.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"طلحة بن مصرف رحمه الله",text:"ما بقي أحد أقرأ مني، ولولا أني أكره أن يُقال لتركت.",source:"سير أعلام النبلاء."},
{cat:"tabieen",narrator:"إبراهيم بن يزيد التيمي رحمه الله",text:"الورع أن تتورع عما سوى الله.",source:"حلية الأولياء."},
{cat:"tabieen",narrator:"داود الطائي رحمه الله",text:"إنما همّك نفسك ففرّغ لها همك.",source:"حلية الأولياء."},
{cat:"atba",narrator:"مالك بن أنس رحمه الله",text:"لن يصلح آخر هذه الأمة إلا بما صلح به أولها.",source:"الشفا للقاضي عياض، وترتيب المدارك."},
{cat:"atba",narrator:"مالك بن أنس رحمه الله",text:"العلم ليس بكثرة الرواية، إنما العلم نور يجعله الله في القلب.",source:"جامع بيان العلم لابن عبد البر."},
{cat:"atba",narrator:"مالك بن أنس رحمه الله",text:"كل أحد يؤخذ من قوله ويُترك إلا صاحب هذا القبر. وأشار إلى قبر النبي صلى الله عليه وسلم.",source:"ابن عبد البر في الجامع."},
{cat:"atba",narrator:"مالك بن أنس رحمه الله",text:"ما أفتيت حتى شهد لي سبعون أني أهل لذلك.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"مالك بن أنس رحمه الله",text:"لا يؤخذ العلم من أربعة: سفيه معلن، وصاحب هوى يدعو إليه، ومن يكذب في أحاديث الناس وإن كان لا يكذب على النبي صلى الله عليه وسلم، ومن لا يعرف هذا الشأن.",source:"الكفاية للخطيب."},
{cat:"atba",narrator:"أبو حنيفة النعمان رحمه الله",text:"لولا أن الناس يأثمون لتركت الإفتاء، فإنما عليّ أن أقول: لا أدري.",source:"مناقب أبي حنيفة للمكي، وسير أعلام النبلاء."},
{cat:"atba",narrator:"أبو حنيفة النعمان رحمه الله",text:"إذا صح الحديث فهو مذهبي.",source:"ابن عبد البر، وابن عابدين في حاشيته."},
{cat:"atba",narrator:"أبو حنيفة النعمان رحمه الله",text:"إياكم وأقوال الرجال، فمن جاء عن أصحاب رسول الله صلى الله عليه وسلم أخذنا به.",source:"ابن عبد البر في الانتقاء."},
{cat:"atba",narrator:"سفيان الثوري رحمه الله",text:"الزهد في الدنيا قصر الأمل، ليس بأكل الغليظ ولا بلبس العباء.",source:"حلية الأولياء."},
{cat:"atba",narrator:"سفيان الثوري رحمه الله",text:"عليك بالعمل، فإن الناس قد فتنوا بالكلام.",source:"حلية الأولياء."},
{cat:"atba",narrator:"سفيان الثوري رحمه الله",text:"ما عالجت شيئًا أشد عليّ من نيتي.",source:"حلية الأولياء."},
{cat:"atba",narrator:"سفيان الثوري رحمه الله",text:"إنما العلم عندنا الرخصة من ثقة، فأما التشديد فيحسنه كل أحد.",source:"جامع بيان العلم."},
{cat:"atba",narrator:"سفيان الثوري رحمه الله",text:"إذا فسد العلماء فسد العالم، وإذا فسد العالَم فسد العلماء.",source:"حلية الأولياء."},
{cat:"atba",narrator:"عبد الرحمن الأوزاعي رحمه الله",text:"اصبر على السنة، وقف حيث وقف القوم.",source:"اللالكائي."},
{cat:"atba",narrator:"عبد الرحمن الأوزاعي رحمه الله",text:"إذا أراد الله بقوم شرًّا فتح عليهم الجدل ومنعهم العمل.",source:"جامع بيان العلم."},
{cat:"atba",narrator:"الليث بن سعد رحمه الله",text:"بلغه أن مالكًا يعمل بعمل أهل المدينة فقال: أحصي عليه سبعين مسألة. وكان الشافعي يقول: الليث أفقه من مالك لولا أصحابه.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"شعبة بن الحجاج رحمه الله",text:"ما سمعت من أحد حديثًا إلا ذهب إليّ فسألته عنه، إلا أن يكون أكبر مني.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"شعبة بن الحجاج رحمه الله",text:"لأن أزني أحب إليّ من أن أدلس. قاله تشديدًا في ذم التدليس.",source:"الكفاية للخطيب."},
{cat:"atba",narrator:"عبد الله بن المبارك رحمه الله",text:"رب عمل صغير تعظمه النية، ورب عمل كبير تصغره النية.",source:"حلية الأولياء."},
{cat:"atba",narrator:"عبد الله بن المبارك رحمه الله",text:"لا يقع موقع الكبر في قلب عبد إلا نقص من عقله بقدر ما دخل من الكبر.",source:"حلية الأولياء."},
{cat:"atba",narrator:"عبد الله بن المبارك رحمه الله",text:"كاد التقى أن يكون خير العمل.",source:"الزهد لابن المبارك."},
{cat:"atba",narrator:"عبد الله بن المبارك رحمه الله",text:"طلبت الأدب ثلاثين سنة، وطلبت العلم عشرين.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"الفضيل بن عياض رحمه الله",text:"من أحب أن يُذكر لم يُذكر، ومن كره أن يُذكر ذُكر.",source:"حلية الأولياء."},
{cat:"atba",narrator:"الفضيل بن عياض رحمه الله",text:"ترك العمل لأجل الناس رياء، والعمل لأجل الناس شرك، والإخلاص أن يعافيك الله منهما.",source:"حلية الأولياء."},
{cat:"atba",narrator:"الفضيل بن عياض رحمه الله",text:"من استوحش من الوحدة واستأنس بالناس لم يسلم من الرياء.",source:"حلية الأولياء."},
{cat:"atba",narrator:"الفضيل بن عياض رحمه الله",text:"أخوف ما أخاف على هذه الأمة الغرور.",source:"حلية الأولياء."},
{cat:"atba",narrator:"إبراهيم بن أدهم رحمه الله",text:"اطلبوا الغنى في القناعة، والراحة في الزهادة، والحرية في التقلل.",source:"حلية الأولياء."},
{cat:"atba",narrator:"إبراهيم بن أدهم رحمه الله",text:"أشد الأعمال ثلاثة: الجود من قلة، والورع في خلوة، وكلمة الحق عند من يُخاف ويُرجى.",source:"حلية الأولياء."},
{cat:"atba",narrator:"وكيع بن الجراح رحمه الله",text:"لو أن الرجل عمل بكل حديث يرويه كان إمامًا.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"وكيع بن الجراح رحمه الله",text:"لا يصلح الحديث إلا لمن كتب، وجمع، وحفظ، وذاكر.",source:"الجامع لأخلاق الراوي."},
{cat:"atba",narrator:"يحيى بن سعيد القطان رحمه الله",text:"ما رأيت الكذب في أحد أكثر منه فيمن يُنسب إلى الخير.",source:"مقدمة صحيح مسلم."},
{cat:"atba",narrator:"عبد الرحمن بن مهدي رحمه الله",text:"لا يجوز أن يكون الرجل إمامًا حتى يعلم ما يصح وما لا يصح.",source:"الكفاية للخطيب."},
{cat:"atba",narrator:"عبد الرحمن بن مهدي رحمه الله",text:"الحفظ الإتقان.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"سفيان بن عيينة رحمه الله",text:"الزهد الصبر وارتفاع الهمة عن الدنيا.",source:"حلية الأولياء."},
{cat:"atba",narrator:"سفيان بن عيينة رحمه الله",text:"العلم إن لم ينفعك ضرك.",source:"جامع بيان العلم."},
{cat:"atba",narrator:"سفيان بن عيينة رحمه الله",text:"أول العلم الاستماع، ثم الإنصات، ثم الحفظ، ثم العمل، ثم النشر.",source:"جامع بيان العلم."},
{cat:"atba",narrator:"معمر بن راشد رحمه الله",text:"ما كتبت سوداء في بيضاء حتى حفظته.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"عبد الملك بن جريج رحمه الله",text:"ما دون العلم إلا من أذن له.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"حماد بن زيد رحمه الله",text:"ما أبالي من خالفني إذا وافقني شعبة.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"حماد بن سلمة رحمه الله",text:"من طلب الحديث لغير الله مكر به.",source:"الجامع لأخلاق الراوي."},
{cat:"atba",narrator:"أبو يوسف القاضي رحمه الله",text:"من طلب غرائب الحديث كذب.",source:"الكفاية للخطيب."},
{cat:"atba",narrator:"محمد بن الحسن الشيباني رحمه الله",text:"إذا صح الخبر عن رسول الله صلى الله عليه وسلم أخذنا به ولم نلتفت إلى غيره.",source:"مناقب الشافعي، والانتقاء."},
{cat:"atba",narrator:"عبد الله بن وهب رحمه الله",text:"لولا أن الله أنقذني بمالك والليث لضللت.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"عبد الرحمن بن القاسم رحمه الله",text:"صحبت مالكًا عشرين سنة، فما سمعت منه كلمة تسقط.",source:"ترتيب المدارك."},
{cat:"atba",narrator:"أشهب بن عبد العزيز رحمه الله",text:"ما رأيت أحدًا أحسن جوابًا من مالك.",source:"ترتيب المدارك."},
{cat:"atba",narrator:"يحيى بن يحيى الليثي رحمه الله",text:"حامل موطأ مالك إلى الأندلس.",source:"ترتيب المدارك."},
{cat:"atba",narrator:"عبد الله بن إدريس رحمه الله",text:"ما كتبت سوداء في بيضاء قط، يعني أنه يحفظ.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"أبو إسحاق الفزاري رحمه الله",text:"كان الأوزاعي إذا رأى أبا إسحاق قال: قد جاء الضيف.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"مخلد بن الحسين رحمه الله",text:"نحن إلى كثير من الأدب أحوج منا إلى كثير من العلم.",source:"جامع بيان العلم."},
{cat:"atba",narrator:"المعافى بن عمران رحمه الله",text:"يقال له ياقوتة العلماء.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"يوسف بن أسباط رحمه الله",text:"يا فتى، الزم السوق فإن الغنى من العافية.",source:"حلية الأولياء."},
{cat:"atba",narrator:"الحسن بن صالح بن حي رحمه الله",text:"ما رأيت أحدًا أخوف من الحسن بن صالح.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"شريك بن عبد الله النخعي رحمه الله",text:"ما رأيت أورع من شريك في القضاء. قاله بعض أصحابه.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"هشيم بن بشير رحمه الله",text:"من لم يكتب الحديث لم يتذوق طعم الفقه.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"يزيد بن هارون رحمه الله",text:"ما رأيت أحدًا أحسن صلاة من يزيد بن هارون. قاله أحمد.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"روح بن عبادة رحمه الله",text:"ما رأيت أحدًا أطلب للعلم بالحجاز من ابن جريج.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"أبو داود الطيالسي رحمه الله",text:"أسرد ثلاثين ألف حديث ولا فخر.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"وهب بن جرير رحمه الله",text:"ما رأيت أسوأ أذانًا من أهل البصرة إلا هذا الحي من الأزد.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"عبد الله بن نمير رحمه الله",text:"كان أحمد يوثقه ويقدّمه.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"أبو نعيم الفضل بن دكين رحمه الله",text:"ما رأيت ابن عيينة يصحّف إلا في حرف.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"عفان بن مسلم رحمه الله",text:"من لم يجمع حديث شعبة فليس محدّثًا.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"أبو الوليد الطيالسي رحمه الله",text:"ما رأيت أكيس من شعبة.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"سعيد بن أبي عروبة رحمه الله",text:"أول من صنّف الأبواب بالبصرة.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"حماد بن أبي سليمان رحمه الله",text:"شيخ أبي حنيفة، وإليه انتهى فقه الكوفة بعد إبراهيم.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"أبو حنيفة النعمان رحمه الله",text:"مثل من يطلب الحديث ولا يتفقه مثل الصيدلاني يجمع الأدوية ولا يدري لأي داء هي.",source:"مناقب أبي حنيفة."},
{cat:"atba",narrator:"مالك بن أنس رحمه الله",text:"إياكم والبدع. قيل: يا أبا عبد الله وما البدع؟ قال: أهل البدع الذين يتكلمون في أسماء الله وصفاته وكلامه وعلمه وقدرته ولا يسكتون عما سكت عنه الصحابة.",source:"ترتيب المدارك، واللالكائي."},
{cat:"atba",narrator:"مالك بن أنس رحمه الله",text:"السنة سفينة نوح، من ركبها نجا ومن تخلف عنها غرق.",source:"تاريخ بغداد، والسير."},
{cat:"atba",narrator:"سفيان الثوري رحمه الله",text:"إذا رأيت الرجل يطير في الهواء ويمشي على الماء لا تغتر به حتى تعرض أمره على الكتاب والسنة.",source:"حلية الأولياء."},
{cat:"atba",narrator:"عبد الله بن المبارك رحمه الله",text:"وهل أفسد الدين إلا الملوك وأحبار سوء ورهبانها.",source:"ديوانه، والسير."},
{cat:"atba",narrator:"عبد الله بن المبارك رحمه الله",text:"رب رجل تمر عليه الآية من كتاب الله كانه ما سمعها وهو دهره يقرؤها.",source:"الزهد لابن المبارك."},
{cat:"atba",narrator:"الفضيل بن عياض رحمه الله",text:"إن الله عبادًا يحيي بهم البلاد، هم أصحاب السنة.",source:"حلية الأولياء."},
{cat:"atba",narrator:"وكيع بن الجراح رحمه الله",text:"لا يكمل الرجل حتى يكتب عمن هو فوقه وعمن هو مثله وعمن هو دونه.",source:"الجامع لأخلاق الراوي."},
{cat:"atba",narrator:"يحيى بن سعيد القطان رحمه الله",text:"ما رأيت أحدًا أحسن أخذًا للحديث ولا أحسن تثبتًا من شعبة.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"عبد الرحمن بن مهدي رحمه الله",text:"إذا سمعت الرجل يقول: دعنا من هذه الأسانيد، فاتهمه.",source:"الكفاية."},
{cat:"atba",narrator:"سفيان بن عيينة رحمه الله",text:"من طلب العلم للدنيا فاته علم الآخرة.",source:"حلية الأولياء."},
{cat:"atba",narrator:"أبو يوسف رحمه الله",text:"العلم شيء لا يعطيك بعضه حتى تعطيه كلك.",source:"جامع بيان العلم."},
{cat:"atba",narrator:"محمد بن الحسن رحمه الله",text:"جودي بالعلم أنفع من جودي بالمال.",source:"مناقب أبي حنيفة."},
{cat:"atba",narrator:"ابن وهب رحمه الله",text:"ما نقلت حديثًا حتى فهمته.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"الأوزاعي رحمه الله",text:"عليك بآثار من سلف وإن رفضك الناس، وإياك وآراء الرجال وإن زخرفوها.",source:"اللالكائي."},
{cat:"atba",narrator:"الأوزاعي رحمه الله",text:"العلم ما جاء عن أصحاب محمد صلى الله عليه وسلم، وما لم يجئ عنهم فليس بعلم.",source:"جامع بيان العلم."},
{cat:"atba",narrator:"الليث بن سعد رحمه الله",text:"ما بتّ ليلة إلا وأنا أعاتب نفسي.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"شعبة رحمه الله",text:"كن في الحديث كالصيرفي في الدراهم.",source:"الكفاية."},
{cat:"atba",narrator:"حماد بن زيد رحمه الله",text:"ما رأيت أحدًا لم يكتب أحفظ من ابن عون.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"أيوب السختياني رحمه الله",text:"إن قوما ابتغوا العلم للدنيا فبخلوا به حتى كأنهم لم يطلبوه.",source:"جامع بيان العلم."},
{cat:"atba",narrator:"يونس بن عبيد رحمه الله",text:"ما استخف رجل بحق الله إلا استخف الناس بحقه.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"ابن عون رحمه الله",text:"ذكر الناس داء، وذكر الله دواء.",source:"حلية الأولياء."},
{cat:"atba",narrator:"هشام بن حسان رحمه الله",text:"ما رأيت أحدًا أطلب للعلم من ابن سيرين.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"جرير بن حازم رحمه الله",text:"ما رأيت أحدًا أحسن صلاة من الحسن.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"مهدي بن ميمون رحمه الله",text:"صحبت ابن سيرين فما رأيت أحدًا أورع منه.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"سلام بن أبي مطيع رحمه الله",text:"كان أيوب السختياني يقوم الليل كله.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"وهيب بن خالد رحمه الله",text:"ما رأيت أحدًا أحفظ من ابن عون.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"إسماعيل بن علية رحمه الله",text:"كان أحمد لا يقدم عليه أحدًا في الحديث.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"عبد الوارث بن سعيد رحمه الله",text:"ما رأيت أحدًا أسرع رجوعًا إلى الحق من حماد بن سلمة.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"بشر بن المفضل رحمه الله",text:"ما رأيت أحدًا أخوف من مالك.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"معتمر بن سليمان رحمه الله",text:"ما رأيت أحدًا أصدق لهجة من أبي.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"عبد الله بن داود الخريبي رحمه الله",text:"ما الكبر إلا أن تزدري الناس.",source:"حلية الأولياء."},
{cat:"atba",narrator:"أبو بكر بن عياش رحمه الله",text:"أدنى نفع السكوت السلامة، وكفى بها عافية.",source:"حلية الأولياء."},
{cat:"atba",narrator:"أبو بكر بن عياش رحمه الله",text:"يا أخي، إياك أن تُرى حيث نهاك الله، أو تُفقد حيث أمرك الله.",source:"حلية الأولياء."},
{cat:"atba",narrator:"شريك القاضي رحمه الله",text:"ما رأيت أحدًا أصبر على الخصوم من شريح.",source:"سير أعلام النبلاء."},
{cat:"atba",narrator:"الحسن بن حي رحمه الله",text:"ما تركت قيام الليل منذ أربعين سنة.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"الشافعي رحمه الله",text:"ما ناظرت أحدًا إلا قلت: اللهم أجر الحق على قلبه ولسانه، فإن كان الحق معي اتبعني، وإن كان معه اتبعته.",source:"آداب الشافعي لابن أبي حاتم."},
{cat:"ulama",narrator:"الشافعي رحمه الله",text:"وددت أن الناس تعلموا هذا العلم ولا يُنسب إليّ منه شيء.",source:"آداب الشافعي."},
{cat:"ulama",narrator:"الشافعي رحمه الله",text:"ما أفلح من طلب العلم بمسألة الغنى.",source:"مناقب الشافعي للبيهقي."},
{cat:"ulama",narrator:"الشافعي رحمه الله",text:"من تعلم القرآن عظمت قيمته، ومن نظر في الفقه نبل مقداره، ومن كتب الحديث قويت حجته.",source:"مناقب الشافعي."},
{cat:"ulama",narrator:"الشافعي رحمه الله",text:"رضى الناس غاية لا تُدرك، فعليك بما ينفعك فالزمه.",source:"مناقب الشافعي."},
{cat:"ulama",narrator:"الشافعي رحمه الله",text:"ما كذبت قط، ولا حلفت بالله صادقًا ولا كاذبًا.",source:"آداب الشافعي."},
{cat:"ulama",narrator:"أحمد بن حنبل رحمه الله",text:"قولوا لأهل البدع بيننا وبينكم الجنائز.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"أحمد بن حنبل رحمه الله",text:"إذا نام الرجل وليس في قلبه شيء من غش المسلمين أصبح وقد غفر له.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"أحمد بن حنبل رحمه الله",text:"ما كتبت حديثًا إلا وقد عملت به.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"أحمد بن حنبل رحمه الله",text:"أعجب الأمور إليّ الإخلاص.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"أحمد بن حنبل رحمه الله",text:"العلم لا يعدله شيء. قيل: التعليم؟ قال: إن كان يُنتفع به.",source:"جامع بيان العلم."},
{cat:"ulama",narrator:"البخاري رحمه الله",text:"ما وضعت في كتابي الصحيح حديثًا إلا اغتسلت قبل ذلك وصليت ركعتين.",source:"تاريخ بغداد، وسير أعلام النبلاء."},
{cat:"ulama",narrator:"البخاري رحمه الله",text:"أخرجت هذا الكتاب من زهاء ست مئة ألف حديث.",source:"تاريخ بغداد."},
{cat:"ulama",narrator:"البخاري رحمه الله",text:"ما رأيت أحدًا أوقر للعلم من أحمد بن حنبل.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"مسلم بن الحجاج رحمه الله",text:"صنفت هذا المسند الصحيح من ثلاث مئة ألف حديث مسموعة.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"أبو داود السجستاني رحمه الله",text:"ذكرت في السنن الصحيح وما يشبهه ويقاربه، وما كان فيه وهن شديد بينته.",source:"رسالته إلى أهل مكة."},
{cat:"ulama",narrator:"الترمذي رحمه الله",text:"جميع ما في هذا الكتاب معمول به وقد أخذ به بعض أهل العلم ما خلا حديثين.",source:"جامع الترمذي في العلل."},
{cat:"ulama",narrator:"النسائي رحمه الله",text:"كان من أشد الأئمة تحرّيًا في الرجال.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"الطبري رحمه الله",text:"لا يحل لأحد أن يفتي في دين الله إلا بعلم.",source:"جامع البيان مقدمة."},
{cat:"ulama",narrator:"ابن خزيمة رحمه الله",text:"ليس لأحد مع رسول الله صلى الله عليه وسلم قول إذا صح الخبر.",source:"صحيح ابن خزيمة."},
{cat:"ulama",narrator:"الدارقطني رحمه الله",text:"انتهى إليه علم الأثر والمعرفة بعلل الحديث في زمانه.",source:"تاريخ بغداد."},
{cat:"ulama",narrator:"البيهقي رحمه الله",text:"من نظر في حديث رسول الله صلى الله عليه وسلم نظر تفهم واستبان له ضعف ما يخالفه من الرأي.",source:"مناقب الشافعي للبيهقي."},
{cat:"ulama",narrator:"الخطيب البغدادي رحمه الله",text:"من نظر في الحديث نظر تفقه استنار قلبه.",source:"الجامع لأخلاق الراوي."},
{cat:"ulama",narrator:"ابن عبد البر رحمه الله",text:"أجمع أهل العلم أن من استبانت له سنة رسول الله صلى الله عليه وسلم لم يكن له أن يدعها لقول أحد.",source:"جامع بيان العلم."},
{cat:"ulama",narrator:"ابن حزم رحمه الله",text:"لا حكم إلا لله، ولا شرع إلا ما جاء به رسول الله صلى الله عليه وسلم.",source:"الإحكام في أصول الأحكام."},
{cat:"ulama",narrator:"ابن حزم رحمه الله",text:"العلم ما قام عليه الدليل، والدعوى بلا دليل دعوى ساقطة.",source:"الفصل، والإحكام."},
{cat:"ulama",narrator:"الجويني رحمه الله",text:"لو استُقبل من الأمر ما استُدبر ما اشتغلت بالكلام.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"الغزالي رحمه الله",text:"العلم بلا عمل جنون، والعمل بلا علم لا يكون.",source:"إحياء علوم الدين."},
{cat:"ulama",narrator:"الغزالي رحمه الله",text:"أكثر الناس جهلًا من ترك علم ما ينفعه واشتغل بعلم ما لا ينفعه.",source:"إحياء علوم الدين."},
{cat:"ulama",narrator:"القاضي عياض رحمه الله",text:"حُب النبي صلى الله عليه وسلم أصل الإيمان.",source:"الشفا بتعريف حقوق المصطفى."},
{cat:"ulama",narrator:"النووي رحمه الله",text:"فينبغي لمن بلغه هذا أن يعمل به وإن لم يكن من أهله.",source:"مقدمة الأربعين النووية."},
{cat:"ulama",narrator:"النووي رحمه الله",text:"مذهبنا أن الحديث إذا صح فهو مذهب الشافعي.",source:"المجموع شرح المهذب."},
{cat:"ulama",narrator:"ابن الصلاح رحمه الله",text:"أصح الكتب بعد كتاب الله الصحيحان.",source:"مقدمة ابن الصلاح."},
{cat:"ulama",narrator:"ابن تيمية رحمه الله",text:"من فارق الدليل ضل السبيل، ولا دليل إلا بما جاء به الرسول.",source:"مجموع الفتاوى."},
{cat:"ulama",narrator:"ابن تيمية رحمه الله",text:"الشريعة جاءت بتحصيل المصالح وتكميلها، وتعطيل المفاسد وتقليلها.",source:"مجموع الفتاوى."},
{cat:"ulama",narrator:"ابن تيمية رحمه الله",text:"الزهد ترك ما لا ينفع في الآخرة، والورع ترك ما تخاف ضرره في الآخرة.",source:"مجموع الفتاوى."},
{cat:"ulama",narrator:"ابن تيمية رحمه الله",text:"ما لا يتم الواجب إلا به فهو واجب.",source:"مجموع الفتاوى."},
{cat:"ulama",narrator:"ابن قيم الجوزية رحمه الله",text:"الجهل داء قاتل، ودواؤه أمران: النص من القرآن أو من السنة، والطبيب هو العالم.",source:"إعلام الموقعين، ومفتاح دار السعادة."},
{cat:"ulama",narrator:"ابن قيم الجوزية رحمه الله",text:"إذا أصبح العبد وأمسى وليس همه إلا الله، تكفل الله سبحانه بما أهمه.",source:"الفوائد."},
{cat:"ulama",narrator:"ابن قيم الجوزية رحمه الله",text:"للصبر سبب عظيم وهو معرفة العبد بأن نفسه ليست له، وإنما هي ملك لسيده.",source:"عدة الصابرين."},
{cat:"ulama",narrator:"ابن قيم الجوزية رحمه الله",text:"القلب يمرض كما يمرض البدن، وشفاؤه في التوبة.",source:"إغاثة اللهفان."},
{cat:"ulama",narrator:"ابن كثير رحمه الله",text:"تفسير القرآن بالقرآن ثم بالسنة ثم بأقوال الصحابة ثم باللغة.",source:"مقدمة تفسير ابن كثير."},
{cat:"ulama",narrator:"الذهبي رحمه الله",text:"ما رأيت أحسن من سكوت الرجل عما لا يعنيه.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"الذهبي رحمه الله",text:"العلم ليس بكثرة الرواية، لكنه نور يقذفه الله في القلب وشرطه الاتباع.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"ابن رجب الحنبلي رحمه الله",text:"العلم النافع هو ما أورث خشية الله.",source:"فضل علم السلف على الخلف."},
{cat:"ulama",narrator:"ابن رجب الحنبلي رحمه الله",text:"من عمل بما علم أورثه الله علم ما لم يعلم.",source:"جامع العلوم والحكم."},
{cat:"ulama",narrator:"ابن حجر العسقلاني رحمه الله",text:"من سلك طريقًا يلتمس فيه علمًا سهل الله له طريقًا إلى الجنة. شرح حديث الصحيح.",source:"فتح الباري."},
{cat:"ulama",narrator:"ابن حجر العسقلاني رحمه الله",text:"القلب إذا كان نقيًّا من الغل والحسد صلح لحلول المعرفة.",source:"فتح الباري في شرح حديث التقوى."},
{cat:"ulama",narrator:"العز بن عبد السلام رحمه الله",text:"الشريعة كلها مصالح، إما درء مفاسد أو جلب مصالح.",source:"قواعد الأحكام."},
{cat:"ulama",narrator:"القرطبي رحمه الله",text:"من لم يكن له من نفسه واعظ لم تنفعه المواعظ.",source:"الجامع لأحكام القرآن."},
{cat:"ulama",narrator:"ابن الجوزي رحمه الله",text:"من لم يحفظ الزمان بالعمل فقد ضيعه.",source:"صيد الخاطر."},
{cat:"ulama",narrator:"ابن الجوزي رحمه الله",text:"يا من أفنى عمره في غير ما خُلق له، استدرك ما بقي فالقليل يكفي.",source:"صيد الخاطر."},
{cat:"ulama",narrator:"ابن قدامة رحمه الله",text:"من لم يسلم للشرع انقاد له الهوى.",source:"روضة الناظر، ولمعة الاعتقاد."},
{cat:"ulama",narrator:"الشاطبي رحمه الله",text:"المقاصد أرواح الأعمال.",source:"الموافقات."},
{cat:"ulama",narrator:"الشاطبي رحمه الله",text:"كل مسألة لا ينبني عليها عمل فالخوض فيها عارية عن النفع.",source:"الموافقات."},
{cat:"ulama",narrator:"ابن دقيق العيد رحمه الله",text:"أصول الفقه يقطع النزاع إذا حُرر.",source:"إحكام الأحكام."},
{cat:"ulama",narrator:"العراقي رحمه الله",text:"لا يحل الرواية إلا عن ثقة.",source:"التقييد والإيضاح."},
{cat:"ulama",narrator:"ابن حجر الهيتمي رحمه الله",text:"من وقع في أعراض العلماء ابتلاه الله بموت القلب.",source:"الفتاوى الحديثية."},
{cat:"ulama",narrator:"السيوطي رحمه الله",text:"من حفظ القرآن عظمت حرمته.",source:"الإتقان."},
{cat:"ulama",narrator:"الشوكاني رحمه الله",text:"إذا صح الدليل فهو مذهبي.",source:"نيل الأوطار، والقول المفيد."},
{cat:"ulama",narrator:"صديق حسن خان رحمه الله",text:"الرجوع إلى الكتاب والسنة هو الدين.",source:"الدين الخالص."},
{cat:"ulama",narrator:"ابن باز رحمه الله",text:"الدعوة إلى التوحيد أول الواجبات.",source:"مجموع فتاوى ابن باز."},
{cat:"ulama",narrator:"ابن عثيمين رحمه الله",text:"العلم يحتاج إلى جمع القلب، وحضور الفهم، وصدق النية.",source:"كتاب العلم."},
{cat:"ulama",narrator:"الألباني رحمه الله",text:"من علامة التوفيق الأخذ بالحديث وترك قول الرجال إذا خالفه.",source:"سلسلة الأحاديث الصحيحة مقدمة."},
{cat:"ulama",narrator:"ابن القيم رحمه الله",text:"الصدق أساس الأعمال، والكذب أساس فسادها.",source:"مدارج السالكين."},
{cat:"ulama",narrator:"ابن تيمية رحمه الله",text:"العبادة اسم جامع لكل ما يحبه الله ويرضاه من الأقوال والأعمال.",source:"العبودية."},
{cat:"ulama",narrator:"النووي رحمه الله",text:"ينبغي للمعلم أن يقصد بتعليمه وجه الله.",source:"المجموع."},
{cat:"ulama",narrator:"الشافعي رحمه الله",text:"ما شبهت الدنيا إلا بظل شجرة، جلست تحتها ثم رحلت.",source:"مناقب الشافعي."},
{cat:"ulama",narrator:"أحمد رحمه الله",text:"أهل الحديث هم الطائفة المنصورة.",source:"سير أعلام النبلاء."},
{cat:"ulama",narrator:"البخاري رحمه الله",text:"لا أعلم شيئًا بعد الإيمان أفضل من طلب العلم.",source:"حلية الأولياء في ترجمته."},
{cat:"ulama",narrator:"مسلم رحمه الله",text:"شرطنا في الصحيح اتصال السند وثقة الرواة وسلامته من الشذوذ والعلة.",source:"مقدمة صحيح مسلم."},
{cat:"ulama",narrator:"أبو داود رحمه الله",text:"ما ذكرت في كتابي حديثًا أجمع الناس على تركه.",source:"رسالته إلى أهل مكة."},
{cat:"ulama",narrator:"الترمذي رحمه الله",text:"الحسن ما لا يكون في إسناده من يتهم بالكذب ولا يكون حديثًا شاذًا.",source:"علل الترمذي."},
{cat:"ulama",narrator:"ابن الصلاح رحمه الله",text:"الحديث الحسن كالصحيح في الاحتجاج عند الفقهاء.",source:"مقدمته."},
{cat:"ulama",narrator:"الخطيب رحمه الله",text:"من أخلص النية في طلب الحديث أعين عليه.",source:"الجامع لأخلاق الراوي."},
{cat:"ulama",narrator:"ابن عبد البر رحمه الله",text:"العلم أشرف ما رغب فيه الراغب.",source:"جامع بيان العلم."},
{cat:"ulama",narrator:"ابن حزم رحمه الله",text:"الواجب أن يحكم بالظاهر، والله يتولى السرائر.",source:"الإحكام."},
{cat:"ulama",narrator:"الغزالي رحمه الله",text:"النية روح العمل.",source:"الإحياء."},
{cat:"ulama",narrator:"العز بن عبد السلام رحمه الله",text:"المكلف لا يترك حق الله لحق نفسه.",source:"قواعد الأحكام."},
{cat:"ulama",narrator:"القرطبي رحمه الله",text:"التدبر هو المقصود من التلاوة.",source:"الجامع لأحكام القرآن."},
{cat:"ulama",narrator:"ابن كثير رحمه الله",text:"القصص في القرآن للعبرة لا لمجرد السمر.",source:"تفسير ابن كثير."},
{cat:"ulama",narrator:"الذهبي رحمه الله",text:"ما زال السلف يوصون بالعلم والعمل جميعًا.",source:"تذكرة الحفاظ."},
{cat:"ulama",narrator:"ابن رجب رحمه الله",text:"من علامات الساعة أن يُرفع العلم بموت العلماء.",source:"جامع العلوم والحكم."},
{cat:"ulama",narrator:"ابن حجر رحمه الله",text:"من سلك الجدد أمن العثار.",source:"هدي الساري."},
{cat:"ulama",narrator:"الشاطبي رحمه الله",text:"التكليف على وفق الاستطاعة.",source:"الموافقات."},
{cat:"ulama",narrator:"ابن قدامة رحمه الله",text:"فرض الكفاية إذا قام به البعض سقط عن الباقين.",source:"المغني."},
{cat:"ulama",narrator:"الجويني رحمه الله",text:"القاعدة أن اليقين لا يزول بالشك.",source:"البرهان، والورقات في المعنى."},
{cat:"ulama",narrator:"القاضي عياض رحمه الله",text:"توقير النبي صلى الله عليه وسلم واجب بعد موته كحياته.",source:"الشفا."},
{cat:"ulama",narrator:"ابن دقيق العيد رحمه الله",text:"النصوص محكمة، والاجتهاد يُعرض عليها لا العكس.",source:"إحكام الأحكام."},
{cat:"ulama",narrator:"العراقي رحمه الله",text:"الموضوع شر الضعيف.",source:"ألفية العراقي."},
{cat:"ulama",narrator:"السيوطي رحمه الله",text:"علوم القرآن أشرف العلوم لتعلقها بكلام الله.",source:"الإتقان."},
{cat:"ulama",narrator:"الشوكاني رحمه الله",text:"التقليد ليس بعلم.",source:"إرشاد الفحول."},
{cat:"ulama",narrator:"ابن باز رحمه الله",text:"من مات على التوحيد دخل الجنة.",source:"فتاواه."},
{cat:"ulama",narrator:"ابن عثيمين رحمه الله",text:"حسن الخلق مع الله أن تتلقى شرعه بالقبول.",source:"شرح رياض الصالحين."},
{cat:"ulama",narrator:"الألباني رحمه الله",text:"لا قول لأحد مع قول رسول الله صلى الله عليه وسلم.",source:"صفة صلاة النبي."},
{cat:"ulama",narrator:"الطبري رحمه الله",text:"غير جائز أن يقول قائل في كتاب الله بغير علم.",source:"جامع البيان."},
{cat:"ulama",narrator:"ابن خزيمة رحمه الله",text:"الكتاب والسنة هما الحجة.",source:"صحيح ابن خزيمة."},
{cat:"ulama",narrator:"الدارقطني رحمه الله",text:"علل الحديث أدق علومه.",source:"العلل."},
{cat:"ulama",narrator:"البيهقي رحمه الله",text:"السنة قاضية على الكتاب في البيان.",source:"دلائل النبوة، والمدخل."},
{cat:"ulama",narrator:"ابن الجوزي رحمه الله",text:"الوقت أنفس ما عُنيت بحفظه.",source:"صيد الخاطر."}
];
